<template>
  <div class="tb" :style="{ '--tb-accent': content?.accentColor || '#c4262e' }" @keydown.esc="closeModal">
    <header class="tb-header">
      <div>
        <div class="tb-eyebrow">NVENT <span>/</span> EU CRA HUB <span>/</span> TEMPLATE MANAGER <span>/</span> TEMPLATE BUILDER</div>
        <div class="tb-title-line"><h1>Template Builder</h1><span v-if="selectedVersion" :class="['tb-status',isDraft?'draft':'published']">{{ versionStatus }}</span></div>
        <p>One workspace to design domains, contributor assessments, reusable tools, shared reviews, rules and publication.</p>
      </div>
      <div class="tb-header-actions">
        <button class="tb-btn tb-outline" type="button" @click="openConnection">⚙ Connection</button>
        <button class="tb-btn tb-outline" type="button" :disabled="!connected||loading" @click="loadAll">↻ Refresh</button>
        <button class="tb-btn tb-outline" type="button" :disabled="!selectedVersion" @click="openPreview">◉ Preview</button>
        <button class="tb-btn tb-primary" type="button" :disabled="!canWrite" @click="openDialog('create')">+ New template</button>
      </div>
    </header>

    <div v-if="!connected" class="tb-message tb-info"><b>Connect to Supabase.</b> Configure Project URL and sb_publishable_ key in WeWeb component properties, or select Connection above. No privileged API keys are used.<button class="tb-btn tb-small" @click="openConnection">Connect</button></div>
    <div v-else-if="!allowWrites" class="tb-message tb-info"><b>Read-only mode.</b> Enable development writes in the WeWeb properties (or the temporary Connection dialog) to create and edit drafts.</div>
    <div v-else class="tb-message tb-warn"><b>Development writes enabled.</b> This component has no Supabase Auth or RLS enforcement. Do not publicly expose the project with broad anonymous write permissions.</div>
    <div v-if="error" class="tb-message tb-error" role="alert"><strong>Supabase error:</strong> {{ error }} <button class="tb-btn tb-small" @click="error=''">Dismiss</button></div>
    <div v-if="notice" class="tb-message tb-success" role="status">{{ notice }} <button class="tb-btn tb-small" @click="notice=''">Dismiss</button></div>

    <section class="tb-context" aria-label="Selected template and version">
      <label>Template
        <select :value="selectedTemplateId||''" @change="chooseTemplate($event.target.value)" :disabled="loading||!cat.templates.length">
          <option value="">Choose a template</option>
          <option v-for="t in cat.templates" :key="t.id" :value="t.id">{{ t.template_code }} · {{ t.template_name }}</option>
        </select>
      </label>
      <label>Version
        <select :value="selectedVersionId||''" @change="chooseVersion($event.target.value)" :disabled="loading||!selectedTemplateId">
          <option value="">Choose version</option>
          <option v-for="v in templateVersions" :key="v.id" :value="v.id">v{{ v.version_major }}.{{ v.version_minor }} — {{ statusOf(v) }}</option>
        </select>
      </label>
      <div class="tb-context-meta"><span>Template</span><strong>{{ selectedTemplate?.template_code || '—' }}</strong></div>
      <div class="tb-context-meta"><span>Revision</span><strong>{{ selectedVersion?.configuration_revision || '—' }}</strong></div>
      <div class="tb-context-meta"><span>Domains</span><strong>{{ g.domains.length }}</strong></div>
      <button v-if="!isDraft && selectedVersion && canWrite" class="tb-btn tb-outline" type="button" :disabled="busy" @click="cloneVersion">Create next draft</button>
    </section>

    <div v-if="loading" class="tb-load">Loading live template data from Supabase…</div>
    <div v-else-if="!selectedVersion" class="tb-empty tb-main-empty">
      <div class="tb-empty-icon">▦</div><h2>Select a template version to begin</h2>
      <p>Existing templates and drafts will appear here after connecting. You can create a new template directly from this page.</p>
      <button class="tb-btn tb-primary" :disabled="!canWrite" @click="openDialog('create')">Create template draft</button>
    </div>
    <template v-else>
      <nav class="tb-tabs" role="tablist" aria-label="Template Builder sections">
        <button v-for="(tab,index) in tabs" :key="tab.id" type="button" role="tab" :aria-selected="activeTab===tab.id" :class="{active:activeTab===tab.id}" @click="activeTab=tab.id"><span>{{ index+1 }}</span>{{ tab.label }}</button>
      </nav>

      <!-- TAB 1: TEMPLATE SETUP -->
      <section v-if="activeTab==='setup'" class="tb-tab-panel" aria-label="Template Setup">
        <div class="tb-section-title"><div><div class="tb-kicker">01 / TEMPLATE SETUP</div><h2>Define your assessment template</h2><p>Manage the master template details and its currently selected version.</p></div><span class="tb-section-tag">{{ selectedTemplate?.template_code }}</span></div>
        <div class="tb-grid-2">
          <div class="tb-card"><h3>Template information</h3><p class="tb-helper">The template name and owning team apply across all its versions.</p>
            <label>Template name<input v-model="setupForm.template_name" maxlength="180" :disabled="!canWrite||!isDraft||hasPublishedSibling" /></label>
            <label>Description<textarea v-model="setupForm.description" rows="4" :disabled="!canWrite||!isDraft||hasPublishedSibling" /></label>
            <label>Owning business team<select v-model="setupForm.owner_team_id" :disabled="!canWrite||!isDraft||hasPublishedSibling"><option value="">Not assigned</option><option v-for="team in cat.teams" :key="team.id" :value="String(team.id)">{{ team.team_name }}</option></select></label>
            <div v-if="hasPublishedSibling" class="tb-inline-note">Master metadata is protected here because this template has a published version. Create a new template to change its shared identity.</div>
          </div>
          <div class="tb-card"><h3>Version details</h3><p class="tb-helper">Published snapshots are immutable. Draft description changes are limited to this version.</p>
            <div class="tb-detail-grid"><div><span>Version</span><b>v{{selectedVersion.version_major}}.{{selectedVersion.version_minor}}</b></div><div><span>Status</span><b>{{ versionStatus }}</b></div><div><span>Updated</span><b>{{ formatDate(selectedVersion.updated_at) }}</b></div><div><span>Revision</span><b>{{ selectedVersion.configuration_revision }}</b></div></div>
            <label>Version description<textarea v-model="setupForm.version_description" rows="4" :disabled="!canWrite||!isDraft" /></label>
            <div class="tb-actions"><button class="tb-btn tb-primary" :disabled="!canWrite||!isDraft||busy" @click="saveSetup">Save template setup</button></div>
          </div>
        </div>
        <div class="tb-grid-3 tb-top-gap"><div class="tb-stat"><span>Domains</span><b>{{g.domains.length}}</b><small>Configured for this version</small></div><div class="tb-stat"><span>Contributor assessments</span><b>{{g.contributors.length}}</b><small>One team per contributor within a domain</small></div><div class="tb-stat"><span>Reusable tools</span><b>{{g.instances.length}}</b><small>Version-bound tool releases</small></div></div>
        <div class="tb-bottom-nav"><button class="tb-btn tb-primary" @click="activeTab='domains'">Continue to Domain Builder →</button></div>
      </section>

      <!-- TAB 2: DOMAIN BUILDER -->
      <section v-else-if="activeTab==='domains'" class="tb-tab-panel" aria-label="Domain Builder">
        <div class="tb-section-title"><div><div class="tb-kicker">02 / DOMAIN BUILDER</div><h2>Domains, contributors and tools</h2><p>Select a domain on the left. Its contributor assessments appear side by side, each with stacked tools.</p></div><button class="tb-btn tb-primary" :disabled="!editable" @click="openDialog('domain')">+ Add domain</button></div>
        <div class="tb-domain-layout">
          <aside class="tb-domain-nav"><div class="tb-subhead">ASSESSMENT DOMAINS <span>{{g.domains.length}}</span></div>
            <button v-for="(d,index) in orderedDomains" :key="d.id" :class="['tb-domain-nav-item',{active:Number(selectedDomainId)===Number(d.id)}]" @click="selectedDomainId=d.id"><b>{{ String(index+1).padStart(2,'0') }}</b><span><strong>{{d.domain_name}}</strong><small>{{ contributorsFor(d.id).length }} contributors · {{ d.domain_code }}</small></span></button>
            <div v-if="!g.domains.length" class="tb-mini-empty">No domains yet.</div>
            <button class="tb-btn tb-subtle tb-full" :disabled="!editable" @click="openDialog('domain')">+ Add domain</button>
          </aside>
          <main class="tb-domain-main" v-if="selectedDomain">
            <div class="tb-domain-heading"><div><div class="tb-kicker">{{ selectedDomain.domain_code }}</div><h3>{{selectedDomain.domain_name}}</h3><p>{{selectedDomain.description||'No description added.'}}</p></div><div class="tb-inline-actions"><button class="tb-btn tb-outline" :disabled="!editable" @click="openDialog('domain',selectedDomain)">Edit domain</button><button class="tb-btn tb-danger-outline" :disabled="!editable" @click="openDelete('DOMAIN',selectedDomain)">Delete domain</button><button class="tb-btn tb-primary" :disabled="!editable||remainingTeams.length===0" @click="openDialog('contributor')">+ Contributor</button></div></div>
            <div class="tb-contributor-strip">
              <div v-for="con in contributorsFor(selectedDomainId)" :key="con.id" class="tb-contributor-card">
                <div class="tb-contributor-head"><div><span class="tb-kicker">CONTRIBUTOR ASSESSMENT</span><h4>{{con.assessment_name}}</h4><div class="tb-team-pill">{{teamName(con.team_id)}}</div></div><div class="tb-inline-actions"><button class="tb-icon-button" type="button" :disabled="!editable" title="Edit contributor" @click="openDialog('contributor',con)">✎</button><button class="tb-icon-button tb-danger-text" type="button" :disabled="!editable" title="Delete contributor assessment" @click="openDelete('CONTRIBUTOR',con)">✕</button></div></div>
                <p class="tb-muted">{{con.description||'Add reusable tools to assemble this contributor assessment.'}}</p>
                <div v-for="inst in instancesFor(con.id)" :key="inst.id" class="tb-tool-card">
                  <div class="tb-tool-head"><div><b>{{inst.instance_name}}</b><small>{{ toolLabel(inst) }}</small></div><div class="tb-inline-actions"><button class="tb-icon-button" type="button" :disabled="!editable" title="Edit tool instance" @click="openDialog('tool',inst)">✎</button><button class="tb-icon-button tb-danger-text" type="button" :disabled="!editable" title="Remove tool instance from this draft (not from the catalogue)" @click="openDelete('TOOL',inst)">✕</button></div></div>
                  <div class="tb-tool-meta"><span>{{sectionsFor(inst.id).length}} sections</span><span>{{questionsForTool(inst.id).length}} questions</span><span :class="{off:inst.is_enabled===false}">{{inst.is_enabled===false?'Disabled':'Enabled'}}</span></div>
                  <div class="tb-tool-actions"><button class="tb-link" @click="toggleTool(inst.id)">{{expandedToolIds.includes(Number(inst.id))?'Hide details':'Edit sections & questions'}} ▾</button><button class="tb-link" @click="openRuleEditor('TOOL_INSTANCE',inst.id,'conditional')">Rules</button></div>
                  <div v-if="expandedToolIds.includes(Number(inst.id))" class="tb-tool-details">
                    <div v-for="s in sectionsFor(inst.id)" :key="s.id" class="tb-section-block"><div class="tb-section-block-head"><strong>{{s.section_name}}</strong><div><button class="tb-link" @click="openRuleEditor('TOOL_SECTION',s.id,'conditional')">Rules</button><button class="tb-link" :disabled="!editable" @click="openDialog('section',s,{toolInstanceId:inst.id})">Edit</button></div></div>
                      <div v-for="q in questionsForSection(s.id)" :key="q.id" class="tb-question-row"><div><b>{{q.question_code}}</b><span>{{q.question_text}}</span><small>{{q.question_type}} · {{optionsFor(q.id).length}} options</small></div><div><button class="tb-link" @click="openRuleEditor('QUESTION',q.id,'conditional')">Rules</button><button class="tb-link" :disabled="!editable" @click="openDialog('question',q,{sectionId:s.id})">Edit</button><button v-if="supportsOptions(q)" class="tb-link" :disabled="!editable" @click="openDialog('option',null,{questionId:q.id})">+ Option</button></div>
                        <div v-if="supportsOptions(q)&&optionsFor(q.id).length" class="tb-option-tags"><button v-for="opt in optionsFor(q.id)" :key="opt.id" class="tb-option-tag" :disabled="!editable" @click="openDialog('option',opt,{questionId:q.id})">{{opt.option_label}} ✎</button></div>
                      </div>
                      <button class="tb-btn tb-small" :disabled="!editable" @click="openDialog('question',null,{sectionId:s.id})">+ Add question</button>
                    </div>
                    <button class="tb-btn tb-outline tb-small tb-full" :disabled="!editable" @click="openDialog('section',null,{toolInstanceId:inst.id})">+ Add section</button>
                    <div v-if="!sectionsFor(inst.id).length" class="tb-mini-empty">No sections. Add a section to configure questions.</div>
                  </div>
                </div>
                <button class="tb-add-tool" :disabled="!editable||!activeReleases.length" @click="openDialog('tool',null,{contributorId:con.id})">+ Add tool from catalogue</button>
              </div>
              <div v-if="!contributorsFor(selectedDomainId).length" class="tb-empty-contributors"><div class="tb-empty-icon">♧</div><h4>No contributor assessments</h4><p>Each contributor belongs to a unique business team within this domain.</p><button class="tb-btn tb-primary" :disabled="!editable||!remainingTeams.length" @click="openDialog('contributor')">+ Add contributor</button></div>
              <button v-else class="tb-new-contributor" :disabled="!editable||!remainingTeams.length" @click="openDialog('contributor')">+<span>Add another contributor</span></button>
            </div>
            <div class="tb-bottom-nav"><button class="tb-btn tb-outline" @click="nextDomain">Next Domain →</button><span>Navigation only. Domain completion occurs in the assessment workflow.</span></div>
          </main>
          <main v-else class="tb-empty">Choose or add a domain to configure its contributors and tools.</main>
        </div>
      </section>

      <!-- TAB 3: DOMAIN-SHARED REVIEW -->
      <section v-else-if="activeTab==='review'" class="tb-tab-panel" aria-label="Review and Approval">
        <div class="tb-section-title"><div><div class="tb-kicker">03 / REVIEW & APPROVAL</div><h2>One review sequence per domain</h2><p>Configure sequential review stages shared across all contributors. Assign eligible teams here; actual reviewers are assigned when releasing assessments.</p></div><button class="tb-btn tb-primary" :disabled="!editable||!selectedDomain" @click="openDialog('stage')">+ Add stage</button></div>
        <div class="tb-message tb-warn tb-contained"><b>Backend integration boundary.</b> Domain-shared stage tables (3A–3H) exist, but template snapshot, full validation and published clone still use the legacy review structure. Stages can be configured in drafts; publishing a version containing them is intentionally blocked until that backend link is completed.</div>
        <div class="tb-review-layout"><aside class="tb-review-nav"><div class="tb-subhead">SELECT DOMAIN</div><button v-for="d in orderedDomains" :key="d.id" :class="['tb-review-domain',{active:Number(d.id)===Number(selectedDomainId)}]" @click="selectedDomainId=d.id">{{d.domain_name}}<span>{{stagesFor(d.id).length}} stages</span></button></aside>
          <div class="tb-review-content" v-if="selectedDomain"><div class="tb-panel-top"><div><h3>{{selectedDomain.domain_name}}</h3><p>{{contributorsFor(selectedDomainId).length}} contributor assessments share this sequence.</p></div><span class="tb-count-pill">{{ stagesFor(selectedDomainId).length }} stages</span></div>
            <div v-if="!stagesFor(selectedDomainId).length" class="tb-zero-stage"><b>Zero-stage review</b><p>When contributors finish their required submissions, the domain can complete without reviewer approval.</p><button class="tb-btn tb-outline" :disabled="!editable" @click="openDialog('stage')">Add an approval stage</button></div>
            <div v-for="(stage,index) in stagesFor(selectedDomainId)" :key="stage.id" class="tb-review-stage"><div class="tb-stage-number">{{index+1}}</div><div class="tb-stage-body"><div class="tb-stage-head"><div><h4>{{stage.stage_name}}</h4><small>{{stage.stage_code}} · {{stage.is_enabled===false?'Disabled':'Enabled'}} · {{stage.is_required===false?'Optional':'Required'}}</small></div><div class="tb-inline-actions"><button class="tb-btn tb-small" :disabled="!editable" @click="openDialog('stage',stage)">Configure</button><button class="tb-btn tb-danger-outline tb-small" :disabled="!editable" @click="openDelete('STAGE',stage)">Delete</button></div></div><p>{{stage.stage_description||'All submitted questions from this domain are in scope.'}}</p><div class="tb-team-tags"><span v-for="teamId in teamIdsForStage(stage.id)" :key="teamId">{{teamName(teamId)}}</span><span v-if="!teamIdsForStage(stage.id).length" class="tb-tag-warning">No reviewer team selected</span></div><div class="tb-stage-foot">Reviewer marks each question Yes / No. No requires comment. Hold returns only No-marked questions to their original contributor.</div></div></div>
            <div class="tb-inline-note">Stages run sequentially. Previously accepted answers remain protected. Reviewers are assigned per assessment at release, not within the template.</div>
          </div><div v-else class="tb-empty">Add a domain before configuring approval stages.</div>
        </div>
      </section>

      <!-- TAB 4: RULES OVERVIEW -->
      <section v-else-if="activeTab==='rules'" class="tb-tab-panel" aria-label="Rules Overview">
        <div class="tb-section-title"><div><div class="tb-kicker">04 / RULES OVERVIEW</div><h2>Conditional, risk, gap and issue rules</h2><p>Browse all rule ownership levels. Configure domain, contributor or tool behavior in the shared editor.</p></div><span class="tb-section-tag">{{g.conditional.length}} conditional · {{g.risk.length}} risk/issue</span></div>
        <div v-for="domain in orderedDomains" :key="domain.id" class="tb-rule-domain"><div class="tb-rule-domain-head"><div><h3>{{domain.domain_name}}</h3><small>{{domain.domain_code}}</small></div><div class="tb-rule-actions"><span>{{ruleCount('DOMAIN',domain.id)}} conditional</span><button class="tb-btn tb-outline tb-small" @click="openRuleEditor('DOMAIN',domain.id,'conditional')">Configure domain</button></div></div>
          <div v-for="con in contributorsFor(domain.id)" :key="con.id" class="tb-rule-contributor"><div class="tb-rule-con-head"><div><strong>{{con.assessment_name}}</strong><small>{{teamName(con.team_id)}}</small></div><div class="tb-rule-actions"><span>{{ruleCount('CONTRIBUTOR',con.id)}} conditional</span><button class="tb-btn tb-outline tb-small" @click="openRuleEditor('CONTRIBUTOR',con.id,'conditional')">Configure contributor</button></div></div>
            <div v-for="inst in instancesFor(con.id)" :key="inst.id" class="tb-rule-tool"><div><b>{{inst.instance_name}}</b><small>{{toolLabel(inst)}}</small></div><div class="tb-rule-actions"><span>{{ruleCount('TOOL_INSTANCE',inst.id)}} conditional · {{risksFor(inst.id).length}} risk/gap/issue</span><button class="tb-btn tb-small" @click="openRuleEditor('TOOL_INSTANCE',inst.id,'conditional')">Conditional</button><button class="tb-btn tb-small" @click="openRuleEditor('TOOL_INSTANCE',inst.id,'risk')">Risk / issue</button></div></div>
            <div v-if="!instancesFor(con.id).length" class="tb-mini-empty">No tools assigned.</div>
          </div>
          <div v-if="!contributorsFor(domain.id).length" class="tb-mini-empty">No contributors assigned.</div>
        </div>
        <div v-if="!g.domains.length" class="tb-empty">No domains configured. Start in Domain Builder.</div>
        <div v-if="ruleEditor.open" class="tb-rule-editor" id="tb-rule-editor"><div class="tb-rule-editor-head"><div><div class="tb-kicker">SHARED RULE EDITOR</div><h3>{{ruleEditor.kind==='risk'?'Risk / gap / issue rules':'Conditional rules'}} · {{targetName(ruleEditor.type,ruleEditor.id)}}</h3></div><button class="tb-icon-button" @click="ruleEditor.open=false">✕</button></div>
          <div v-if="ruleEditor.kind==='conditional'"><div v-for="r in rulesForTarget(ruleEditor.type,ruleEditor.id)" :key="r.id" class="tb-rule-row"><div><b>{{r.rule_name}}</b><small>{{r.action_type}} · {{r.condition_logic}} · {{r.is_enabled===false?'Disabled':'Enabled'}}</small><div v-for="c in conditionsFor(r.id)" :key="c.id" class="tb-condition-line">{{questionName(c.source_id)}} · {{c.condition_operator}} · {{conditionDisplay(c)}} <button class="tb-link" :disabled="!editable" @click="openDialog('condition',c,{ruleId:r.id})">Edit condition</button> <button class="tb-link tb-danger-text" :disabled="!editable" @click="openDelete('CONDITION',c)">Delete</button></div></div><div class="tb-rule-row-buttons"><button class="tb-btn tb-small" :disabled="!editable" @click="openDialog('condition',null,{ruleId:r.id})">+ Condition</button><button class="tb-btn tb-small" :disabled="!editable" @click="openDialog('conditional',r,{targetType:ruleEditor.type,targetId:ruleEditor.id})">Edit rule</button><button class="tb-btn tb-danger-outline tb-small" :disabled="!editable" @click="openDelete('CONDITIONAL',r)">Delete</button></div></div>
            <button class="tb-btn tb-primary tb-small" :disabled="!editable" @click="openDialog('conditional',null,{targetType:ruleEditor.type,targetId:ruleEditor.id})">+ Add conditional rule</button></div>
          <div v-else><div v-for="r in risksFor(ruleEditor.id)" :key="r.id" class="tb-rule-row"><div><b>{{r.rule_name}}</b><small>{{r.rule_code}} · {{r.rule_type}} · {{r.severity||'Unrated'}} · {{r.is_enabled===false?'Disabled':'Enabled'}}</small></div><button class="tb-btn tb-small" :disabled="!editable" @click="openDialog('risk',r,{toolInstanceId:ruleEditor.id})">Edit rule</button></div><button class="tb-btn tb-primary tb-small" :disabled="!editable" @click="openDialog('risk',null,{toolInstanceId:ruleEditor.id})">+ Add risk / issue rule</button><p class="tb-helper">Advanced rule JSON is validated by the existing PostgreSQL rule validator. This editor does not silently invent scoring conditions.</p></div>
        </div>
      </section>

      <!-- TAB 5: VALIDATE & PUBLISH -->
      <section v-else-if="activeTab==='publish'" class="tb-tab-panel" aria-label="Validation and Publish">
        <div class="tb-section-title"><div><div class="tb-kicker">05 / VALIDATION & PUBLISH</div><h2>Validate, preview and publish</h2><p>Preview incomplete drafts whenever you want. Final validation is required before publication.</p></div><button class="tb-btn tb-outline" @click="openPreview">◉ Preview draft</button></div>
        <div class="tb-grid-3"><div class="tb-stat"><span>Domains</span><b>{{g.domains.length}}</b><small>{{g.domains.filter(d=>contributorsFor(d.id).length).length}} with contributors</small></div><div class="tb-stat"><span>Questions</span><b>{{g.questions.length}}</b><small>{{g.questions.filter(x=>x.is_enabled!==false).length}} enabled</small></div><div class="tb-stat"><span>Review stages</span><b>{{g.stages.length}}</b><small>Domain-shared configuration</small></div></div>
        <div v-if="g.stages.length" class="tb-message tb-warn tb-contained"><strong>Publication blocked for this version:</strong> the 3A–3H domain-shared review tables are not yet included in the published template snapshot and cloning logic. Publishing now could lose the approved review design. The rest of the Template Builder remains usable.</div>
        <div class="tb-grid-2 tb-top-gap"><div class="tb-card"><h3>Validation status</h3><p class="tb-helper">Runs the existing <code>cra_tm_run_full_template_validation</code> function for the selected DRAFT version.</p><div class="tb-detail-grid"><div><span>Status</span><b>{{latestValidation ? (latestValidation.ready_for_publication?'READY':'NOT READY'):'NOT RUN'}}</b></div><div><span>Revision</span><b>{{latestValidation?.configuration_revision||'—'}}</b></div><div><span>Completed checks</span><b>{{latestValidation?.completed_checks??'—'}}</b></div><div><span>Failed checks</span><b>{{latestValidation?.failed_checks??'—'}}</b></div></div><div class="tb-actions"><button class="tb-btn tb-primary" :disabled="!editable||busy||!actorId" @click="validateDraft">{{busy?'Working…':'Run full validation'}}</button><button class="tb-btn tb-outline" @click="openPreview">Preview</button></div></div>
          <div class="tb-card"><h3>Publish version</h3><p class="tb-helper">Published versions are immutable. Publish requires a fresh successful full validation, a valid actor and all publication integrations.</p><div class="tb-criteria"><div :class="{pass:isDraft}">{{isDraft?'✓':'×'}} Draft version selected</div><div :class="{pass:latestValidation?.ready_for_publication===true}">{{latestValidation?.ready_for_publication?'✓':'×'}} Passed full validation</div><div :class="{pass:!g.stages.length}">{{!g.stages.length?'✓':'×'}} Domain-shared snapshot integration safe</div><div :class="{pass:!!actorId}">{{actorId?'✓':'×'}} Actor user profile configured</div><div :class="{pass:content?.enablePublication===true}">{{content?.enablePublication?'✓':'×'}} Publication enabled in WeWeb properties</div></div><button class="tb-btn tb-primary tb-full" type="button" :disabled="!canPublish||busy" @click="openDialog('publish')">Publish immutable version</button></div></div>
        <div class="tb-card tb-top-gap" v-if="validationResults.length"><h3>Most recent validation details</h3><div v-for="r in validationResults" :key="r.id" class="tb-validation-row"><span :class="['tb-result',{fail:r.validation_status==='FAIL'}]">{{r.validation_status}}</span><div><b>{{r.validation_code}}</b><p>{{r.validation_message}}</p></div><small>{{r.severity}}</small></div></div>
        <div class="tb-inline-note">A saved draft can be previewed without creating submissions, review verdicts or real assessment records.</div>
      </section>
    </template>

    <!-- ALL FIVE TABS USE THIS ONE SHARED DIALOG + STATE -->
    <div v-if="dialog" class="tb-overlay" @click.self="closeModal"><form class="tb-dialog" @submit.prevent="saveDialog" role="dialog" aria-modal="true" :aria-label="dialogTitle"><div class="tb-dialog-head"><div><span class="tb-kicker">TEMPLATE BUILDER</span><h2>{{dialogTitle}}</h2></div><button class="tb-icon-button" type="button" @click="closeModal" aria-label="Close dialog">✕</button></div>
        <div class="tb-dialog-body">
          <template v-if="dialog==='connection'"><p class="tb-helper">Temporary session settings. To persist them after import, use WeWeb component properties.</p><label>Supabase Project URL<input v-model.trim="form.url" type="url" placeholder="https://your-project.supabase.co" required autocomplete="off" /></label><label>Publishable key<input v-model.trim="form.key" type="password" placeholder="sb_publishable_…" required autocomplete="off" /></label><label>Actor user_profiles.id<input v-model.number="form.actor" type="number" min="1" /></label><label class="tb-checkline"><input v-model="form.writes" type="checkbox" /> Enable development writes (unsafe without Auth/RLS)</label></template>
          <template v-else-if="dialog==='create'"><label>Template name<input v-model.trim="form.name" required maxlength="180" /></label><label>Description<textarea v-model="form.description" rows="3" /></label><label>Owner team<select v-model="form.team_id"><option value="">Not assigned</option><option v-for="t in cat.teams" :key="t.id" :value="String(t.id)">{{t.team_name}}</option></select></label></template>
          <template v-else-if="dialog==='domain'"><label>Domain name<input v-model.trim="form.name" required maxlength="180" /></label><label>Description<textarea v-model="form.description" rows="3" /></label><label>Display order<input v-model.number="form.order" type="number" min="0" /></label></template>
          <template v-else-if="dialog==='contributor'"><label>Contributor assessment name<input v-model.trim="form.name" required /></label><label>Business team<select v-model="form.team_id" required :disabled="!!form.id"><option value="">Select team</option><option v-for="t in form.id?cat.teams:remainingTeams" :key="t.id" :value="String(t.id)">{{t.team_name}}</option></select></label><label>Description<textarea v-model="form.description" rows="3" /></label><label>Display order<input v-model.number="form.order" type="number" min="0" /></label></template>
          <template v-else-if="dialog==='tool'"><label>Tool instance name<input v-model.trim="form.name" required /></label><label>Reusable tool release<select v-model="form.release_id" required :disabled="!!form.id"><option value="">Select a release</option><option v-for="r in activeReleases" :key="r.id" :value="String(r.id)">{{releaseLabel(r)}}</option></select></label><label>Description<textarea v-model="form.description" rows="3" /></label><label>Display order<input v-model.number="form.order" type="number" min="0" /></label><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label></template>
          <template v-else-if="dialog==='section'"><label>Section name<input v-model.trim="form.name" required /></label><label>Description<textarea v-model="form.description" rows="3" /></label><label>Display order<input v-model.number="form.order" type="number" min="0" /></label><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label></template>
          <template v-else-if="dialog==='question'"><label>Question code <small>(stable identifier)</small><input v-model.trim="form.code" required :disabled="!!form.id" /></label><label>Question text<textarea v-model.trim="form.question" required rows="3" /></label><label>Friendly name<input v-model.trim="form.friendly_name" /></label><label>Question type<select v-model="form.question_type" required @change="onQuestionTypeChange"><option v-for="qt in activeQuestionTypes" :key="qt.type_code" :value="qt.type_code">{{qt.type_name}} ({{qt.type_code}})</option></select></label>
            <div v-if="questionHasOptions" class="tb-inline-option-editor">
              <div class="tb-inline-option-heading"><strong>Answer options</strong><small>{{questionIsMulti?'Respondents may select multiple answers':'Respondents select one answer'}}</small></div>
              <p class="tb-helper">Configure options here, just like in a questionnaire builder. Existing option values are stable IDs; only their labels and hints can change. Each option is stored in Supabase.</p>
              <div v-for="(o,index) in form.optionDrafts" :key="o.draftKey||o.id" class="tb-inline-option-row">
                <div class="tb-inline-option-top"><span>{{index+1}}.</span><input v-model.trim="o.option_label" required placeholder="Option label" @input="onOptionLabelInput(index)"/><button type="button" class="tb-icon-button tb-danger-text" :disabled="form.question_type==='YES_NO'" title="Remove answer option" @click="removeInlineOption(index)">✕</button></div>
                <div class="tb-dialog-grid"><label>Stable value<input v-model.trim="o.option_value" :disabled="!!o.id||form.question_type==='YES_NO'" required /></label><label>Hint<input v-model="o.option_hint" placeholder="Optional guidance" /></label></div>
                <div class="tb-check-grid"><label class="tb-checkline"><input type="checkbox" v-model="o.is_enabled" /> Enabled</label><label class="tb-checkline"><input type="checkbox" :checked="o.is_default===true" @change="toggleInlineDefault(index,$event.target.checked)"/> Default</label></div>
              </div>
              <button v-if="form.question_type!=='YES_NO'" type="button" class="tb-btn tb-outline tb-small" @click="addInlineOption">+ Add answer option</button>
              <div v-if="form.id&&form.originalQuestionType!==form.question_type" class="tb-inline-note">Changes to question type are checked against existing answer options and rule references. An incompatible conversion is blocked rather than deleting data.</div>
            </div>
            <div v-else class="tb-inline-note">This question type accepts a direct answer. It does not require answer-option records.</div>
            <label>Description<textarea v-model="form.description" rows="3" /></label><label>Question hint<input v-model="form.hint" /></label><label>Display order<input v-model.number="form.order" type="number" min="0" /></label><div class="tb-check-grid"><label class="tb-checkline"><input v-model="form.required" type="checkbox" /> Required</label><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label><label class="tb-checkline"><input v-model="form.attachments" type="checkbox" /> Allow attachment</label><label class="tb-checkline"><input v-model="form.comments" type="checkbox" /> Allow comment</label></div></template>
          <template v-else-if="dialog==='option'"><label>Option value <small>(stable identifier)</small><input v-model.trim="form.value" required :disabled="!!form.id" /></label><label>Option label<input v-model.trim="form.label" required /></label><label>Option hint<input v-model="form.hint" /></label><label>Display order<input v-model.number="form.order" type="number" min="0" /></label><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label><label class="tb-checkline"><input v-model="form.is_default" type="checkbox" /> Selected by default</label></template>
          <template v-else-if="dialog==='stage'"><label>Stage name<input v-model.trim="form.name" required /></label><label>Stage code<input v-model.trim="form.code" required :disabled="!!form.id" /></label><label>Description<textarea v-model="form.description" rows="3" /></label><label>Sequence order<input v-model.number="form.order" type="number" min="1" /></label><div class="tb-check-grid"><label class="tb-checkline"><input v-model="form.required" type="checkbox" /> Required</label><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label></div><p class="tb-helper">Eligible reviewer teams (actual named reviewers are assigned at assessment release):</p><div class="tb-check-teams"><label v-for="t in cat.teams" :key="t.id" class="tb-checkline"><input type="checkbox" :checked="form.teamIds.includes(Number(t.id))" @change="toggleFormTeam(t.id,$event.target.checked)" /> {{t.team_name}}</label></div></template>
          <template v-else-if="dialog==='conditional'"><label>Rule name<input v-model.trim="form.name" required /></label><label>Description<textarea v-model="form.description" rows="3" /></label><div class="tb-dialog-grid"><label>Action<select v-model="form.action"><option v-for="a in ['SHOW','HIDE','REQUIRE','MAKE_OPTIONAL','ENABLE','DISABLE']" :key="a">{{a}}</option></select></label><label>Condition logic<select v-model="form.logic"><option>AND</option><option>OR</option></select></label></div><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label><div class="tb-inline-note">Add conditions separately after creating this rule.</div></template>
          <template v-else-if="dialog==='condition'"><label>Source question<select v-model="form.source_id" required @change="onConditionSourceChange"><option value="">Select question</option><option v-for="q in g.questions" :key="q.id" :value="String(q.id)">{{q.question_code}} — {{q.question_text.slice(0,70)}}</option></select></label>
            <label>Condition operator<select v-model="form.operator" required><option v-for="op in conditionOperatorChoices" :key="op" :value="op">{{op.replaceAll('_',' ')}}</option></select></label>
            <div v-if="conditionIsChoice&&!['IS_EMPTY','IS_NOT_EMPTY'].includes(form.operator)" class="tb-inline-option-editor"><b>Match selected answer options</b><p class="tb-helper">These are real option IDs from the chosen source question. The database stores their mappings, not manually entered JSON.</p><label v-for="o in optionsFor(form.source_id)" :key="o.id" class="tb-checkline"><input type="checkbox" :checked="form.optionIds.includes(Number(o.id))" @change="toggleConditionOption(o.id,$event.target.checked)"/> {{o.option_label}} ({{o.option_value}})</label><div v-if="!optionsFor(form.source_id).length" class="tb-form-error">Add answer options to the source question first.</div></div>
            <label v-else-if="!['IS_EMPTY','IS_NOT_EMPTY'].includes(form.operator)">Comparison value<input v-model="form.compareValue" placeholder="Value to compare" /></label>
            <div class="tb-inline-note">Conditions and option mappings are persisted using the existing PostgreSQL rule functions. Unsupported rule operators are not offered.</div></template>
          <template v-else-if="dialog==='delete'"><div class="tb-message tb-warn tb-contained"><b>Draft-only deletion</b><p>{{form.deleteSummary}}</p><p>Dependent draft records are removed only when backend references permit it. Audited tool instances and executed or published records remain protected. A database constraint may block deletion until rules or other references are resolved.</p></div><label>Type DELETE to confirm<input v-model.trim="form.confirmText" autocomplete="off" placeholder="DELETE" required /></label></template>
          <template v-else-if="dialog==='risk'"><label>Rule code<input v-model.trim="form.code" required :disabled="!!form.id" /></label><label>Rule name<input v-model.trim="form.name" required /></label><div class="tb-dialog-grid"><label>Type<select v-model="form.rule_type"><option>RISK</option><option>GAP</option><option>ISSUE</option></select></label><label>Severity<select v-model="form.severity"><option value="">Not specified</option><option v-for="sev in ['CRITICAL','HIGH','MEDIUM','LOW','INFORMATIONAL']" :key="sev">{{sev}}</option></select></label></div><label>Description<textarea v-model="form.description" rows="3" /></label><label>Condition logic<select v-model="form.logic"><option>OR</option><option>AND</option></select></label><label>Score <small>(optional)</small><input v-model="form.score" type="number" min="0" step="0.01" /></label><label>Conditions (JSON array)<textarea v-model="form.conditions_json" rows="5" spellcheck="false" /></label><label>Output configuration (JSON object)<textarea v-model="form.output_json" rows="3" spellcheck="false" /></label><label class="tb-checkline"><input v-model="form.enabled" type="checkbox" /> Enabled</label></template>
          <template v-else-if="dialog==='publish'"><div class="tb-message tb-warn tb-contained">Publishing will create an immutable snapshot for version v{{selectedVersion.version_major}}.{{selectedVersion.version_minor}}. This cannot be edited afterward.</div><label>Publication notes<textarea v-model="form.notes" rows="3" maxlength="2000" /></label><label class="tb-checkline"><input v-model="form.confirm" type="checkbox" required /> I confirm the validation is current and this version is ready to publish.</label></template>
          <p v-if="formError" class="tb-form-error" role="alert">{{formError}}</p>
        </div>
        <footer class="tb-dialog-footer"><button type="button" class="tb-btn tb-outline" @click="closeModal">Cancel</button><button class="tb-btn tb-primary" type="submit" :disabled="busy||(dialog!=='connection'&&!canWrite)||((dialog==='publish')&&!canPublish)||(dialog==='delete'&&form.confirmText!=='DELETE')">{{busy?'Saving…':dialog==='connection'?'Connect':dialog==='publish'?'Confirm publication':dialog==='delete'?'Delete draft item':'Save changes'}}</button></footer>
      </form></div>

    <!-- GLOBAL PREVIEW: local state only; no database writes -->
    <div v-if="previewOpen" class="tb-overlay tb-preview-overlay" @click.self="previewOpen=false"><section class="tb-preview" role="dialog" aria-modal="true" aria-label="Template Preview"><header class="tb-preview-head"><div><div class="tb-kicker">SIMULATION / NO SUBMISSIONS CREATED</div><h2>{{selectedTemplate?.template_name}} <small>v{{selectedVersion?.version_major}}.{{selectedVersion?.version_minor}}</small></h2></div><div class="tb-inline-actions"><span class="tb-preview-badge">PREVIEW ONLY</span><button class="tb-icon-button" @click="previewOpen=false" aria-label="Close preview">✕</button></div></header>
        <div class="tb-preview-toolbar"><label>Domain<select v-model="previewDomainId" @change="onPreviewDomainChange"><option v-for="d in orderedDomains" :key="d.id" :value="String(d.id)">{{d.domain_name}}</option></select></label><label>Contributor<select v-model="previewContributorId" @change="onPreviewContributorChange"><option v-for="con in contributorsFor(previewDomainId)" :key="con.id" :value="String(con.id)">{{con.assessment_name}} · {{teamName(con.team_id)}}</option></select></label><label v-if="previewMode==='reviewer'&&stagesFor(previewDomainId).length">Review stage<select v-model="previewStageId"><option v-for="s in stagesFor(previewDomainId)" :key="s.id" :value="String(s.id)">{{s.stage_name}}</option></select></label><div class="tb-preview-mode"><button :class="{active:previewMode==='contributor'}" @click="previewMode='contributor'">Contributor view</button><button :class="{active:previewMode==='reviewer'}" @click="previewMode='reviewer'">Reviewer view</button></div></div>
        <div class="tb-preview-content"><div v-if="!previewContributor" class="tb-empty">Choose a domain with configured contributors to preview its questions.</div><div v-else-if="previewHidden('DOMAIN',previewDomainId)||previewHidden('CONTRIBUTOR',previewContributorId)" class="tb-empty">This domain or contributor is hidden by its current conditional rules. Change the source answers or rules to preview it.</div><template v-else><div v-if="previewMode==='reviewer'" class="tb-message tb-info tb-contained">Reviewer simulation: mark each question Yes or No. No requires a comment for the hypothetical Hold. No verdicts are saved.</div><div v-else class="tb-message tb-info tb-contained">Contributor simulation: question answers, conditional visibility and controls are local to this preview, not submitted or auto-saved.</div>
          <div v-for="inst in instancesFor(previewContributorId)" :key="inst.id" class="tb-preview-tool"><template v-if="!previewHidden('TOOL_INSTANCE',inst.id)"><h3>{{inst.instance_name}}</h3><p v-if="!isQuestionnaireTool(inst)" class="tb-inline-note">This release is {{toolLabel(inst)}}. Dedicated tool-type rendering may require its own implemented renderer; generic configured questions are shown where present.</p>
              <div v-for="section in sectionsFor(inst.id)" :key="section.id"><template v-if="!previewHidden('TOOL_SECTION',section.id)"><h4>{{section.section_name}}</h4><div v-for="q in questionsForSection(section.id)" :key="q.id"><div v-if="!previewHidden('QUESTION',q.id)" class="tb-preview-question"><div class="tb-preview-q-head"><b>{{q.question_code}} · {{q.question_text}}</b><span v-if="q.is_required||visibilityForQuestion(q).required">Required</span><span v-if="visibilityForQuestion(q).unknown" class="tb-tag-warning">Conditional simulation limited</span></div><p v-if="q.description">{{q.description}}</p><div v-if="previewMode==='contributor'" class="tb-preview-answer"><template v-if="supportsOptions(q)"><label v-for="o in optionsFor(q.id)" :key="o.id" class="tb-preview-choice"><input v-if="isMulti(q)" type="checkbox" :checked="Array.isArray(previewAnswers[q.id])&&previewAnswers[q.id].includes(o.option_value)" @change="changeMultiAnswer(q.id,o.option_value,$event.target.checked)" :disabled="visibilityForQuestion(q).disabled" /><input v-else type="radio" :name="`preview-${q.id}`" :value="o.option_value" v-model="previewAnswers[q.id]" :disabled="visibilityForQuestion(q).disabled" />{{o.option_label}}</label><span v-if="!optionsFor(q.id).length" class="tb-inline-note">No answer options configured.</span></template><textarea v-else-if="['LONG_TEXT','TEXTAREA'].includes(q.question_type)" v-model="previewAnswers[q.id]" rows="3" :disabled="visibilityForQuestion(q).disabled" /><input v-else :type="inputTypeFor(q)" v-model="previewAnswers[q.id]" :disabled="visibilityForQuestion(q).disabled" :placeholder="q.question_hint||'Enter response'" /></div>
                    <div v-else class="tb-preview-verdict"><label><input type="radio" :name="`verdict-${q.id}`" value="YES" v-model="previewVerdicts[q.id]" /> Yes — Accept</label><label><input type="radio" :name="`verdict-${q.id}`" value="NO" v-model="previewVerdicts[q.id]" /> No — Hold</label><textarea v-if="previewVerdicts[q.id]==='NO'" v-model="previewComments[q.id]" rows="2" placeholder="Required reviewer comment explaining the correction" /></div></div></div></template></div>
            </template></div>
          <div v-if="previewMode==='reviewer'" class="tb-preview-foot"><div><b>{{previewNoCount}} questions marked No</b><p>{{previewNoCount?'Only these questions would return to contributors after a valid Hold.':'No questions selected for Hold.'}}</p></div><button class="tb-btn tb-outline" @click="previewMode='contributor'">Back to contributor view</button><button class="tb-btn tb-primary" :disabled="!previewNoCount||!validPreviewComments" @click="previewFeedback='Simulated Hold: '+previewNoCount+' question(s) would be sent for correction.'">Simulate Hold</button></div>
          <div v-if="previewFeedback" class="tb-message tb-success tb-contained">{{previewFeedback}}</div></template></div>
        <footer class="tb-preview-footer"><span>Local preview only · no database changes</span><button class="tb-btn tb-primary" @click="previewOpen=false">Close preview</button></footer>
      </section></div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, nextTick } from 'vue';
import { createApi, eq, positiveId, publicKey, projectUrl, codeToken, unwrap, T } from './api.mjs';
import { isChoice, isMany, optionSeed, verifyOptions, conditionOperators, conditionInputValue } from './question-editor.mjs';
import { emptyGraph, sorted, visibilityFor } from './logic.mjs';

const props=defineProps({content:{type:Object,required:true}});
const emit=defineEmits(['trigger-event']);
const content=computed(()=>props.content||{});
const tabs=[{id:'setup',label:'Template Setup'},{id:'domains',label:'Domain Builder'},{id:'review',label:'Review & Approval'},{id:'rules',label:'Rules Overview'},{id:'publish',label:'Validation & Publish'}];
const emptyCat=()=>({templates:[],versions:[],versionStatuses:[],templateStatuses:[],teams:[],users:[],tools:[],releases:[],questionTypes:[]});
const cat=ref(emptyCat()),g=ref(emptyGraph()),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const activeTab=ref('setup'),selectedTemplateId=ref(0),selectedVersionId=ref(0),selectedDomainId=ref(0),expandedToolIds=ref([]);
const dialog=ref(''),form=ref({}),formError=ref(''),dialogContext=ref({}),ruleEditor=ref({open:false,kind:'conditional',type:'',id:0});
const setupForm=ref({template_name:'',description:'',owner_team_id:'',version_description:''});
const latestValidation=ref(null),validationResults=ref([]);
const previewOpen=ref(false),previewDomainId=ref(''),previewContributorId=ref(''),previewStageId=ref(''),previewMode=ref('contributor');
const previewAnswers=ref({}),previewVerdicts=ref({}),previewComments=ref({}),previewFeedback=ref('');
const connectionOverride=ref(null);
const effectiveConnection=computed(()=>connectionOverride.value||{url:content.value.supabaseUrl||'',key:content.value.publishableKey||'',actor:content.value.actorUserId||0,writes:content.value.enableMutations===true});
const connected=computed(()=>{try{projectUrl(effectiveConnection.value.url);publicKey(effectiveConnection.value.key);return true;}catch{return false;}});
const actorId=computed(()=>{const id=Number(effectiveConnection.value.actor);return Number.isSafeInteger(id)&&id>0?id:0;});
const allowWrites=computed(()=>effectiveConnection.value.writes===true);
const canWrite=computed(()=>connected.value&&allowWrites.value&&!busy.value);
const api=computed(()=>connected.value?createApi({url:effectiveConnection.value.url,key:effectiveConnection.value.key}):null);
const selectedTemplate=computed(()=>cat.value.templates.find(x=>Number(x.id)===Number(selectedTemplateId.value))||null);
const selectedVersion=computed(()=>cat.value.versions.find(x=>Number(x.id)===Number(selectedVersionId.value))||null);
const versionStatus=computed(()=>statusOf(selectedVersion.value));
const isDraft=computed(()=>versionStatus.value==='DRAFT');
const editable=computed(()=>canWrite.value&&isDraft.value);
const templateVersions=computed(()=>cat.value.versions.filter(x=>Number(x.template_id)===Number(selectedTemplateId.value)).sort((a,b)=>b.version_major-a.version_major||b.version_minor-a.version_minor));
const hasPublishedSibling=computed(()=>templateVersions.value.some(x=>statusOf(x)!=='DRAFT'));
const orderedDomains=computed(()=>sorted(g.value.domains));
const selectedDomain=computed(()=>g.value.domains.find(d=>Number(d.id)===Number(selectedDomainId.value))||null);
const activeReleases=computed(()=>cat.value.releases.filter(r=>r.is_active!==false&&cat.value.tools.find(t=>Number(t.id)===Number(r.tool_id))?.is_active!==false));
const activeQuestionTypes=computed(()=>cat.value.questionTypes.filter(t=>t.is_active!==false));
const questionHasOptions=computed(()=>dialog.value==='question'&&isChoice(cat.value.questionTypes,form.value.question_type));
const questionIsMulti=computed(()=>isMany(cat.value.questionTypes,form.value.question_type));
const conditionSourceQuestion=computed(()=>g.value.questions.find(q=>Number(q.id)===Number(form.value.source_id))||null);
const conditionIsChoice=computed(()=>isChoice(cat.value.questionTypes,conditionSourceQuestion.value?.question_type));
const conditionOperatorChoices=computed(()=>conditionOperators(conditionSourceQuestion.value?.question_type));
const remainingTeams=computed(()=>{const used=new Set(contributorsFor(selectedDomainId.value).map(c=>Number(c.team_id)));return cat.value.teams.filter(t=>!used.has(Number(t.id)));});
const canPublish=computed(()=>editable.value&&!!actorId.value&&content.value.enablePublication===true&&!g.value.stages.length&&latestValidation.value?.ready_for_publication===true&&Number(latestValidation.value.configuration_revision)===Number(selectedVersion.value?.configuration_revision));
const previewContributor=computed(()=>g.value.contributors.find(x=>Number(x.id)===Number(previewContributorId.value))||null);
const previewNoCount=computed(()=>Object.values(previewVerdicts.value).filter(x=>x==='NO').length);
const validPreviewComments=computed(()=>Object.entries(previewVerdicts.value).every(([id,v])=>v!=='NO'||String(previewComments.value[id]||'').trim().length>0));
const dialogNames={connection:'Supabase connection',create:'Create template draft',domain:'Domain details',contributor:'Contributor assessment',tool:'Reusable tool instance',section:'Tool section',question:'Tool question',option:'Answer option',stage:'Domain review stage',conditional:'Conditional rule',condition:'Rule condition',risk:'Risk / gap / issue rule',publish:'Confirm publication',delete:'Confirm draft deletion'};
const dialogTitle=computed(()=>dialogNames[dialog.value]||'Edit');
const trigger=(name,event={})=>emit('trigger-event',{name,event});
function statusOf(v){if(!v)return '—';return cat.value.versionStatuses.find(s=>Number(s.id)===Number(v.status_id))?.status_code||'UNKNOWN';}
function teamName(id){return cat.value.teams.find(t=>Number(t.id)===Number(id))?.team_name||`Team #${id}`;}
function releaseFor(inst){return cat.value.releases.find(r=>Number(r.id)===Number(inst.tool_release_id));}
function toolFor(inst){return cat.value.tools.find(t=>Number(t.id)===Number(releaseFor(inst)?.tool_id));}
function releaseLabel(r){const t=cat.value.tools.find(x=>Number(x.id)===Number(r.tool_id));return `${t?.tool_name||'Tool #'+r.tool_id} · ${r.release_version} (${t?.tool_type||'unknown'})`;}
function toolLabel(inst){const t=toolFor(inst),r=releaseFor(inst);return `${t?.tool_name||'Tool'} · ${r?.release_version||'Release unknown'}`;}
function isQuestionnaireTool(inst){return /CHECKLIST|QUESTION|SURVEY|FORM/i.test(toolFor(inst)?.tool_type||'');}
function contributorsFor(domainId){return sorted(g.value.contributors.filter(x=>Number(x.domain_id)===Number(domainId)));}
function instancesFor(contributorId){return sorted(g.value.instances.filter(x=>Number(x.contributor_assessment_id)===Number(contributorId)));}
function sectionsFor(instId){return sorted(g.value.sections.filter(x=>Number(x.tool_instance_id)===Number(instId)&&x.is_enabled!==false));}
function questionsForSection(secId){return sorted(g.value.questions.filter(x=>Number(x.tool_section_id)===Number(secId)&&x.is_enabled!==false));}
function questionsForTool(instId){return sectionsFor(instId).flatMap(s=>questionsForSection(s.id));}
function optionsFor(qId){return sorted(g.value.options.filter(o=>Number(o.question_id)===Number(qId)&&o.is_enabled!==false));}
function stagesFor(domainId){return [...g.value.stages.filter(s=>Number(s.domain_id)===Number(domainId))].sort((a,b)=>a.stage_order-b.stage_order||a.id-b.id);}
function teamIdsForStage(stageId){return g.value.stageTeams.filter(st=>Number(st.domain_review_stage_id)===Number(stageId)).map(st=>Number(st.team_id));}
function rulesForTarget(type,id){return g.value.conditional.filter(r=>r.target_type===type&&Number(r.target_id)===Number(id));}
function conditionsFor(id){return sorted(g.value.conditions.filter(c=>Number(c.conditional_rule_id)===Number(id)));}
function risksFor(instId){return sorted(g.value.risk.filter(r=>Number(r.tool_instance_id)===Number(instId)));}
function ruleCount(type,id){return rulesForTarget(type,id).length;}
function questionName(id){const q=g.value.questions.find(x=>Number(x.id)===Number(id));return q?.question_code||`Source #${id}`;}
function targetName(type,id){if(type==='DOMAIN')return g.value.domains.find(x=>Number(x.id)===Number(id))?.domain_name||id;if(type==='CONTRIBUTOR')return g.value.contributors.find(x=>Number(x.id)===Number(id))?.assessment_name||id;if(type==='TOOL_SECTION')return g.value.sections.find(x=>Number(x.id)===Number(id))?.section_name||id;if(type==='QUESTION')return g.value.questions.find(x=>Number(x.id)===Number(id))?.question_code||id;return g.value.instances.find(x=>Number(x.id)===Number(id))?.instance_name||id;}
function conditionDisplay(c){const mapped=g.value.conditionOptions.filter(o=>Number(o.condition_id)===Number(c.id));if(mapped.length)return mapped.map(m=>g.value.options.find(o=>Number(o.id)===Number(m.answer_option_id))?.option_label||'#'+m.answer_option_id).join(', ');return JSON.stringify(c.condition_value||{}).slice(0,120);}
function supportsOptions(q){const qt=cat.value.questionTypes.find(x=>x.type_code===q.question_type);return qt?.supports_options===true;}
function isMulti(q){return cat.value.questionTypes.find(t=>t.type_code===q.question_type)?.supports_multiple_values===true;}
function inputTypeFor(q){const key=String(q.question_type||'').toUpperCase();return ({NUMBER:'number',DATE:'date',DATETIME:'datetime-local',EMAIL:'email',URL:'url'})[key]||'text';}
function formatDate(value){if(!value)return '—';try{return new Date(value).toLocaleDateString();}catch{return String(value);}}
function fillSetup(){setupForm.value={template_name:selectedTemplate.value?.template_name||'',description:selectedTemplate.value?.description||'',owner_team_id:selectedTemplate.value?.owner_team_id?String(selectedTemplate.value.owner_team_id):'',version_description:selectedVersion.value?.description||''};}
function syncDomain(){if(!g.value.domains.find(d=>Number(d.id)===Number(selectedDomainId.value)))selectedDomainId.value=orderedDomains.value[0]?.id||0;}
function resetValidation(){latestValidation.value=null;validationResults.value=[];}
async function loadAll(){if(!api.value)return;loading.value=true;error.value='';try{cat.value=await api.value.catalogue();const wanted=Number(content.value.initialTemplateVersionId||0);let version=cat.value.versions.find(v=>Number(v.id)===Number(selectedVersionId.value))||cat.value.versions.find(v=>Number(v.id)===wanted)||[...cat.value.versions].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at))[0];if(version){selectedTemplateId.value=version.template_id;await selectVersion(version.id);}else{selectedVersionId.value=0;g.value=emptyGraph();}}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function reloadGraph({keepValidation=false}={}){if(!api.value||!selectedVersionId.value)return;const [graph,version]=await Promise.all([api.value.graph(selectedVersionId.value),api.value.get(T.versions,selectedVersionId.value)]);g.value=graph;if(version){const index=cat.value.versions.findIndex(v=>Number(v.id)===Number(version.id));if(index>=0)cat.value.versions[index]=version;}syncDomain();fillSetup();if(!keepValidation)resetValidation();}
async function selectVersion(value){const version=cat.value.versions.find(v=>Number(v.id)===Number(value));if(!version)return;selectedVersionId.value=Number(value);selectedTemplateId.value=Number(version.template_id);error.value='';ruleEditor.value.open=false;resetValidation();await reloadGraph();trigger('template-selected',{template_id:selectedTemplateId.value,template_version_id:selectedVersionId.value});}
async function chooseVersion(value){if(!value)return;loading.value=true;try{await selectVersion(value);}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function chooseTemplate(value){if(!value){selectedTemplateId.value=0;selectedVersionId.value=0;g.value=emptyGraph();return;}selectedTemplateId.value=Number(value);if(templateVersions.value.length)await chooseVersion(templateVersions.value[0].id);else{selectedVersionId.value=0;g.value=emptyGraph();}}
async function run(action,{area='builder',refresh=true,validation=false}={}){if(!editable.value&&!['create','clone'].includes(area))throw new Error('Draft editing is disabled. Choose a DRAFT version and enable development writes.');busy.value=true;formError.value='';error.value='';try{const result=await action();if(refresh)await reloadGraph({keepValidation:validation});if(!validation)resetValidation();notice.value=`${area} saved successfully.`;trigger('draft-saved',{template_version_id:selectedVersionId.value,area});return result;}catch(e){formError.value=e.message;error.value=e.message;throw e;}finally{busy.value=false;}}
async function saveSetup(){if(!editable.value)return;busy.value=true;try{const p=setupForm.value;if(!p.template_name.trim())throw new Error('Template name is required.');if(!hasPublishedSibling.value){await api.value.patch(T.templates,selectedTemplateId.value,{template_name:p.template_name.trim(),description:p.description.trim()||null,owner_team_id:p.owner_team_id?positiveId(p.owner_team_id):null});}
  await api.value.patch(T.versions,selectedVersionId.value,{description:p.version_description.trim()||null});cat.value=await api.value.catalogue();await reloadGraph();notice.value='Template Setup saved.';trigger('draft-saved',{template_version_id:selectedVersionId.value,area:'setup'});
}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function cloneVersion(){if(!canWrite.value||!actorId.value){error.value='Set an existing actor user_profiles.id before cloning.';return;}busy.value=true;try{const out=unwrap(await api.value.rpc('cra_tm_clone_published_version',{p_source_version_id:positiveId(selectedVersionId.value),p_actor_user_id:actorId.value}));cat.value=await api.value.catalogue();await selectVersion(out.new_template_version_id);activeTab.value='setup';notice.value='New draft version cloned.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
function nextDomain(){const index=orderedDomains.value.findIndex(d=>Number(d.id)===Number(selectedDomainId.value));const next=orderedDomains.value[index+1];if(next)selectedDomainId.value=next.id;else notice.value='You are on the last domain. Next Domain is navigation only.';}
function toggleTool(id){const n=Number(id);expandedToolIds.value=expandedToolIds.value.includes(n)?expandedToolIds.value.filter(x=>x!==n):[...expandedToolIds.value,n];}
function openConnection(){openDialog('connection');}
async function openRuleEditor(type,id,kind='conditional'){ruleEditor.value={open:true,type,id:Number(id),kind};activeTab.value='rules';await nextTick();document.getElementById('tb-rule-editor')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
function openDialog(kind,item=null,ctx={}){
  formError.value='';dialogContext.value=ctx;dialog.value=kind;
  const x=item||{};const nextOrder=(rows,field='display_order')=>1+Math.max(0,...rows.map(y=>Number(y[field])||0));
  if(kind==='connection')form.value={url:effectiveConnection.value.url,key:effectiveConnection.value.key,actor:effectiveConnection.value.actor,writes:effectiveConnection.value.writes};
  else if(kind==='create')form.value={name:'',description:'',team_id:''};
  else if(kind==='domain')form.value={id:x.id||null,name:x.domain_name||'',description:x.description||'',order:x.display_order??nextOrder(g.value.domains),configuration:x.configuration||{}};
  else if(kind==='contributor')form.value={id:x.id||null,name:x.assessment_name||'',team_id:x.team_id?String(x.team_id):'',description:x.description||'',order:x.display_order??nextOrder(contributorsFor(selectedDomainId.value)),configuration:x.configuration||{}};
  else if(kind==='tool')form.value={id:x.id||null,contributorId:ctx.contributorId||x.contributor_assessment_id,name:x.instance_name||'',release_id:x.tool_release_id?String(x.tool_release_id):'',description:x.description||'',order:x.display_order??nextOrder(instancesFor(ctx.contributorId)),enabled:x.is_enabled!==false,configuration:x.configuration||{}};
  else if(kind==='section')form.value={id:x.id||null,toolInstanceId:ctx.toolInstanceId||x.tool_instance_id,name:x.section_name||'',description:x.description||'',order:x.display_order??nextOrder(sectionsFor(ctx.toolInstanceId)),enabled:x.is_enabled!==false,configuration:x.configuration||{}};
  else if(kind==='question')form.value={id:x.id||null,sectionId:ctx.sectionId||x.tool_section_id,code:x.question_code||`Q_${Date.now().toString(36).toUpperCase()}`,question:x.question_text||'',question_type:x.question_type||activeQuestionTypes.value[0]?.type_code||'',friendly_name:x.friendly_name||'',description:x.description||'',hint:x.question_hint||'',order:x.display_order??nextOrder(questionsForSection(ctx.sectionId)),required:x.is_required===true,enabled:x.is_enabled!==false,attachments:x.allows_attachment===true,comments:x.allows_comment===true,configuration:x.configuration||{},validation_rules:x.validation_rules||{},originalQuestionType:x.question_type||'',optionDrafts:x.id?g.value.options.filter(o=>Number(o.question_id)===Number(x.id)).map(o=>({...o,draftKey:'existing-'+o.id})):optionSeed(x.question_type||activeQuestionTypes.value[0]?.type_code||'').map((o,i)=>({...o,draftKey:'seed-'+i}))};
  else if(kind==='option')form.value={id:x.id||null,questionId:ctx.questionId||x.question_id,value:x.option_value||'',label:x.option_label||'',hint:x.option_hint||'',order:x.display_order??nextOrder(optionsFor(ctx.questionId)),enabled:x.is_enabled!==false,is_default:x.is_default===true,configuration:x.configuration||{}};
  else if(kind==='stage')form.value={id:x.id||null,name:x.stage_name||'',code:x.stage_code||`STAGE_${stagesFor(selectedDomainId.value).length+1}`,description:x.stage_description||'',order:x.stage_order??(stagesFor(selectedDomainId.value).reduce((m,s)=>Math.max(m,Number(s.stage_order)),0)+1),required:x.is_required!==false,enabled:x.is_enabled!==false,teamIds:x.id?teamIdsForStage(x.id):[]};
  else if(kind==='conditional')form.value={id:x.id||null,targetType:ctx.targetType||x.target_type,targetId:ctx.targetId||x.target_id,name:x.rule_name||'',description:x.description||'',action:x.action_type||'SHOW',logic:x.condition_logic||'AND',enabled:x.is_enabled!==false,configuration:x.configuration||{}};
  else if(kind==='condition')form.value={id:x.id||null,ruleId:ctx.ruleId||x.conditional_rule_id,source_id:x.source_id?String(x.source_id):'',operator:x.condition_operator||'EQUALS',value_json:JSON.stringify(x.condition_value||{},null,2),compareValue:String(x.condition_value?.value??''),optionIds:x.id?g.value.conditionOptions.filter(o=>Number(o.condition_id)===Number(x.id)).map(o=>Number(o.answer_option_id)):[]};
  else if(kind==='risk')form.value={id:x.id||null,toolInstanceId:ctx.toolInstanceId||x.tool_instance_id,code:x.rule_code||`RULE_${Date.now().toString(36).toUpperCase()}`,name:x.rule_name||'',description:x.description||'',rule_type:x.rule_type||'RISK',severity:x.severity||'',logic:x.condition_logic||'OR',score:x.score??'',conditions_json:JSON.stringify(x.conditions||[],null,2),output_json:JSON.stringify(x.output_configuration||{},null,2),aggregation_configuration:x.aggregation_configuration||{},enabled:x.is_enabled!==false};
  else if(kind==='publish')form.value={notes:'',confirm:false};
  else if(kind==='delete')form.value={deleteKind:ctx.deleteKind,itemId:x.id,confirmText:'',deleteSummary:ctx.deleteSummary};
}
function openDelete(kind,item){
  const label={DOMAIN:item.domain_name,CONTRIBUTOR:item.assessment_name,TOOL:item.instance_name,STAGE:item.stage_name,OPTION:item.option_label,CONDITION:'Condition #'+item.id,CONDITIONAL:item.rule_name}[kind]||('#'+item.id);
  openDialog('delete',item,{deleteKind:kind,deleteSummary:`Delete ${kind.toLowerCase()} “${label}” from this draft? This cannot be undone.`});
}
function newOptionRow(){return {draftKey:'new-'+Date.now()+'-'+Math.random().toString(36).slice(2),option_value:'',option_label:'',option_hint:'',is_enabled:true,is_default:false};}
function addInlineOption(){form.value.optionDrafts.push(newOptionRow());}
function removeInlineOption(index){form.value.optionDrafts.splice(index,1);}
function onOptionLabelInput(index){const o=form.value.optionDrafts[index];if(o&&!o.id&&!o.option_value)o.option_value=codeToken(o.option_label);}
function toggleInlineDefault(index,checked){if(!questionIsMulti.value&&checked)form.value.optionDrafts.forEach((o,j)=>{if(j!==index)o.is_default=false;});form.value.optionDrafts[index].is_default=checked;}
function onQuestionTypeChange(){const x=form.value;
  if(!isChoice(cat.value.questionTypes,x.question_type))return;
  if(x.question_type==='YES_NO'&&!x.optionDrafts.some(o=>o.id))x.optionDrafts=optionSeed('YES_NO').map((o,i)=>({...o,draftKey:'seed-'+i}));
  if(x.question_type!=='YES_NO'&&!x.id&&x.optionDrafts.length===2&&x.optionDrafts.every(o=>['YES','NO'].includes(o.option_value)))x.optionDrafts=[];
}
function onConditionSourceChange(){form.value.optionIds=[];form.value.operator=conditionOperatorChoices.value[0]||'EQUALS';form.value.compareValue='';}
function toggleConditionOption(id,checked){const n=Number(id);form.value.optionIds=checked?[...new Set([...form.value.optionIds,n])]:form.value.optionIds.filter(x=>x!==n);}
async function deleteDraftItem(kind,id){return api.value.rpc('cra_tm_delete_draft_item',{p_kind:kind,p_id:positiveId(id),p_template_version_id:positiveId(selectedVersionId.value),p_confirm:true});}
function closeModal(){if(!busy.value){dialog.value='';formError.value='';}}
function toggleFormTeam(id,checked){const n=Number(id);form.value.teamIds=checked?[...new Set([...form.value.teamIds,n])]:form.value.teamIds.filter(x=>Number(x)!==n);}
function parseJSON(text,type='object'){let value;try{value=JSON.parse(String(text||'').trim());}catch{throw new Error(`Invalid JSON: expected ${type}.`);}if(type==='array'&&!Array.isArray(value))throw new Error('Expected a JSON array.');if(type==='object'&&(value===null||typeof value!=='object'||Array.isArray(value)))throw new Error('Expected a JSON object.');return value;}
async function saveDialog(){const kind=dialog.value,x=form.value;
  if(kind==='connection') {try{projectUrl(x.url);publicKey(x.key);connectionOverride.value={url:x.url.trim(),key:x.key.trim(),actor:Number(x.actor||0),writes:x.writes===true};closeModal();selectedVersionId.value=0;selectedTemplateId.value=0;await loadAll();}catch(e){formError.value=e.message;}return;}
  if(kind==='create'){if(!canWrite.value||!actorId.value){formError.value='An existing actor user_profiles.id is required to create templates.';return;}busy.value=true;try{const out=unwrap(await api.value.rpc('cra_tm_create_template_draft',{p_template_name:x.name.trim(),p_created_by:actorId.value,p_description:x.description||null,p_owner_team_id:x.team_id?positiveId(x.team_id):null,p_metadata:{}}));cat.value=await api.value.catalogue();await selectVersion(out.template_version_id);activeTab.value='setup';dialog.value='';formError.value='';notice.value='New template draft created.';trigger('draft-created',{template_id:out.template_id,template_version_id:out.template_version_id});}catch(e){formError.value=e.message;}finally{busy.value=false;}return;}
  if(kind==='publish'){await publishConfirmed();return;}
  if(kind==='delete'){
    if(x.confirmText!=='DELETE'){formError.value='Enter DELETE exactly to confirm.';return;}
    try{await run(()=>deleteDraftItem(x.deleteKind,x.itemId),{area:'deleted '+x.deleteKind.toLowerCase()});dialog.value='';notice.value=`${x.deleteKind} deleted from draft. Published records and catalogue definitions were not changed.`;}
    catch(e){formError.value=e.message+' Check that sql/01_draft_deletion_rpc_v1_1.sql is installed and your current Supabase role is authorized.';}
    return;
  }
  if(!editable.value){formError.value='Choose a draft and enable development writes.';return;}
  try{await run(async()=>{
    let output;
    if(kind==='domain')output=await api.value.rpc('cra_tm_save_domain',{p_template_version_id:positiveId(selectedVersionId.value),p_domain_name:x.name,p_domain_id:x.id||null,p_description:x.description||null,p_display_order:Number(x.order||0),p_configuration:x.configuration||{}});
    else if(kind==='contributor')output=await api.value.rpc('cra_tm_save_contributor_assessment',{p_domain_id:positiveId(selectedDomainId.value),p_assessment_name:x.name,p_team_id:positiveId(x.team_id),p_contributor_assessment_id:x.id||null,p_description:x.description||null,p_display_order:Number(x.order||0),p_configuration:x.configuration||{}});
    else if(kind==='tool'){if(!actorId.value)throw new Error('Actor user_profiles.id is required for tool instances.');output=await api.value.rpc('cra_tm_save_tool_instance',{p_contributor_assessment_id:positiveId(x.contributorId),p_instance_name:x.name,p_tool_release_id:positiveId(x.release_id),p_actor_user_id:actorId.value,p_tool_instance_id:x.id||null,p_description:x.description||null,p_display_order:Number(x.order||0),p_is_enabled:x.enabled,p_configuration:x.configuration||{}});}
    else if(kind==='section')output=await api.value.rpc('cra_tm_save_tool_section',{p_tool_instance_id:positiveId(x.toolInstanceId),p_section_name:x.name,p_section_id:x.id||null,p_description:x.description||null,p_display_order:Number(x.order||0),p_is_enabled:x.enabled,p_configuration:x.configuration||{}});
    else if(kind==='question'){
      const supports=isChoice(cat.value.questionTypes,x.question_type);
      const before=x.id?g.value.questions.find(q=>Number(q.id)===Number(x.id)):null;
      const persisted=before?g.value.options.filter(o=>Number(o.question_id)===Number(x.id)):[];
      if(before&&before.question_type!==x.question_type&&persisted.length&&isChoice(cat.value.questionTypes,before.question_type)!==supports)throw new Error('Incompatible type change: remove the existing answer options from the original choice question first, then change its type. Published records remain protected.');
      if(supports)verifyOptions(x.optionDrafts,x.question_type,isMany(cat.value.questionTypes,x.question_type));
      output=await api.value.rpc('cra_tm_save_tool_question',{p_tool_section_id:positiveId(x.sectionId),p_question_text:x.question,p_question_type:x.question_type,p_question_code:x.id?x.code:codeToken(x.code),p_question_id:x.id||null,p_friendly_name:x.friendly_name||null,p_description:x.description||null,p_question_hint:x.hint||null,p_display_order:Number(x.order||0),p_is_required:x.required,p_is_enabled:x.enabled,p_allows_attachment:x.attachments,p_allows_comment:x.comments,p_validation_rules:x.validation_rules||{},p_configuration:x.configuration||{}});
      const qid=x.id||unwrap(output)?.question_id;
      if(!qid)throw new Error('Question saved but returned no ID; refresh before adding options.');
      if(supports){
        for(let i=0;i<x.optionDrafts.length;i++){
          const o=x.optionDrafts[i];
          await api.value.rpc('cra_tm_save_tool_answer_option',{p_question_id:positiveId(qid),p_option_label:o.option_label.trim(),p_option_value:o.option_value.trim(),p_answer_option_id:o.id||null,p_option_hint:o.option_hint||null,p_display_order:i+1,p_is_default:o.is_default===true,p_is_enabled:o.is_enabled!==false,p_configuration:o.configuration||{}});
        }
        const retained=new Set(x.optionDrafts.map(o=>Number(o.id)).filter(Boolean));
        for(const o of persisted)if(!retained.has(Number(o.id)))await deleteDraftItem('OPTION',o.id);
      }
    }
    else if(kind==='option')output=await api.value.rpc('cra_tm_save_tool_answer_option',{p_question_id:positiveId(x.questionId),p_option_label:x.label,p_option_value:x.value,p_answer_option_id:x.id||null,p_option_hint:x.hint||null,p_display_order:Number(x.order||0),p_is_default:x.is_default,p_is_enabled:x.enabled,p_configuration:x.configuration||{}});
    else if(kind==='stage'){
      const payload={stage_name:x.name.trim(),stage_description:x.description||null,stage_order:Number(x.order),is_required:x.required,is_enabled:x.enabled,updated_at:new Date().toISOString()};
      if(x.id){output=await api.value.patch(T.stages,x.id,payload);}else{output=await api.value.insert(T.stages,{domain_id:positiveId(selectedDomainId.value),stage_code:codeToken(x.code),...payload,configuration:{}});}
      const stageId=x.id||unwrap(output)?.id;if(!stageId)throw new Error('Stage was saved, but no ID was returned. Refresh before editing its teams.');
      const old= g.value.stageTeams.filter(st=>Number(st.domain_review_stage_id)===Number(stageId));const oldIds=new Set(old.map(s=>Number(s.team_id)));const desired=new Set(x.teamIds.map(Number));
      for(const membership of old)if(!desired.has(Number(membership.team_id)))await api.value.remove(T.stageTeams,membership.id);
      for(const tid of desired)if(!oldIds.has(tid))await api.value.insert(T.stageTeams,{domain_review_stage_id:stageId,team_id:tid});
      selectedDomainId.value=Number(selectedDomainId.value);
    }
    else if(kind==='conditional')output=await api.value.rpc('cra_tm_save_conditional_rule',{p_template_version_id:positiveId(selectedVersionId.value),p_rule_name:x.name,p_target_type:x.targetType,p_target_id:positiveId(x.targetId),p_action_type:x.action,p_rule_id:x.id||null,p_description:x.description||null,p_condition_logic:x.logic,p_is_enabled:x.enabled,p_configuration:x.configuration||{}});
    else if(kind==='condition'){
      const source=g.value.questions.find(q=>Number(q.id)===Number(x.source_id));
      if(!source)throw new Error('Select an existing source question.');
      if(!conditionOperators(source.question_type).includes(x.operator))throw new Error('This operator is incompatible with the source question type.');
      const choice=isChoice(cat.value.questionTypes,source.question_type);
      if(choice&&!x.optionIds.length)throw new Error('Select one or more answer options for this choice-based condition.');
      if(choice&&['EQUALS','NOT_EQUALS'].includes(x.operator)&&x.optionIds.length!==1)throw new Error('Equals/Not Equals requires exactly one selected answer option. Use Contains Any for several options.');
      const conditionValue=choice?{}:conditionInputValue(source.question_type,x.operator,x.compareValue);
      output=await api.value.rpc('cra_tm_save_rule_condition',{p_rule_id:positiveId(x.ruleId),p_source_type:'QUESTION',p_source_id:positiveId(x.source_id),p_condition_operator:x.operator,p_condition_id:x.id||null,p_condition_group:1,p_group_logic:'AND',p_is_enabled:true,p_condition_value:conditionValue});
      const conditionId=x.id||unwrap(output)?.condition_id;
      if(!conditionId)throw new Error('Condition saved without an ID. Refresh before mapping options.');
      await api.value.rpc('cra_tm_set_condition_answer_options',{p_condition_id:positiveId(conditionId),p_answer_option_ids:choice?x.optionIds.map(positiveId):[]});
    }
    else if(kind==='risk')output=await api.value.rpc('cra_tm_save_risk_issue_rule',{p_tool_instance_id:positiveId(x.toolInstanceId),p_rule_code:x.id?x.code:codeToken(x.code),p_rule_name:x.name,p_rule_type:x.rule_type,p_rule_id:x.id||null,p_description:x.description||null,p_condition_logic:x.logic,p_conditions:parseJSON(x.conditions_json,'array'),p_severity:x.severity||null,p_score:x.score===''?null:Number(x.score),p_is_enabled:x.enabled,p_output_configuration:parseJSON(x.output_json,'object'),p_aggregation_configuration:x.aggregation_configuration||{}});
    if(kind==='domain'&&!x.id)selectedDomainId.value=unwrap(output)?.domain_id||selectedDomainId.value;
    if(kind==='tool'){const id=unwrap(output)?.tool_instance_id;if(id&&!expandedToolIds.value.includes(Number(id)))expandedToolIds.value.push(Number(id));}
    return output;
  },{area:kind});closeModal();}catch(e){formError.value=e.message;}
}
async function validateDraft(){if(!editable.value||!actorId.value)return;busy.value=true;error.value='';try{const out=unwrap(await api.value.rpc('cra_tm_run_full_template_validation',{p_template_version_id:positiveId(selectedVersionId.value),p_initiated_by:actorId.value}));await reloadGraph({keepValidation:true});latestValidation.value=out;validationResults.value=await api.value.rows(T.validationResults,{validation_run_id:`eq.${out.validation_run_id}`});notice.value=out.ready_for_publication?'Validation passed.':'Validation finished with outstanding checks.';trigger('validation-completed',{template_version_id:selectedVersionId.value,ready:out.ready_for_publication});}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function publishConfirmed(){if(!canPublish.value||form.value.confirm!==true){formError.value='Publication prerequisites or confirmation are missing.';return;}busy.value=true;try{await api.value.rpc('cra_tm_publish_template_version',{p_template_version_id:positiveId(selectedVersionId.value),p_validation_run_id:latestValidation.value.validation_run_id,p_actor_user_id:actorId.value,p_publication_notes:form.value.notes||null});cat.value=await api.value.catalogue();await reloadGraph({keepValidation:true});dialog.value='';formError.value='';notice.value='Published immutable template version.';trigger('template-published',{template_version_id:selectedVersionId.value});}catch(e){formError.value=e.message;}finally{busy.value=false;}}
function openPreview(){if(!selectedVersion.value)return;previewDomainId.value=String(selectedDomainId.value||orderedDomains.value[0]?.id||'');onPreviewDomainChange();previewMode.value='contributor';previewFeedback.value='';previewOpen.value=true;}
function onPreviewContributorChange(){previewVerdicts.value={};previewComments.value={};previewFeedback.value='';previewAnswers.value={};}
function onPreviewDomainChange(){previewContributorId.value=String(contributorsFor(previewDomainId.value)[0]?.id||'');previewStageId.value=String(stagesFor(previewDomainId.value)[0]?.id||'');previewVerdicts.value={};previewComments.value={};previewFeedback.value='';}
function visibilityForQuestion(q){return visibilityFor('QUESTION',q.id,g.value,previewAnswers.value);}
function previewHidden(type,id){return visibilityFor(type,id,g.value,previewAnswers.value).hidden===true;}
function changeMultiAnswer(id,value,checked){const existing=Array.isArray(previewAnswers.value[id])?previewAnswers.value[id]:[];previewAnswers.value[id]=checked?[...new Set([...existing,value])]:existing.filter(v=>v!==value);}
watch(()=>[content.value.supabaseUrl,content.value.publishableKey],()=>{if(!connectionOverride.value)loadAll();});
onMounted(()=>{if(connected.value)loadAll();});
